from pathlib import Path
import subprocess,json,datetime,sys,hashlib
out=Path(__file__).resolve().parents[1];phase=sys.argv[1];cases={'fields-empty':'figure.caption([C]).fields()','fields-explicit':'figure.caption([C],position:top,separator:[--]).fields()','body':'figure.caption([C]).body','func-equality':'figure.caption([C]).func()==figure.caption','func-repr':'repr(figure.caption([C]).func())','encoded':'json.encode(figure.caption([C]))','kind-element':'figure([A],kind:figure.caption)','position':'figure.caption([C],position:top).position'};cases.update({'body-none':'figure.caption(none).body','body-str':'figure.caption("C").body','body-symbol':'figure.caption(sym.alpha).body','separator-none':'figure.caption([C],separator:none).fields()','separator-str':'figure.caption([C],separator:"S").fields()','separator-auto':'figure.caption([C],separator:auto).fields()','fields-explicit-text':'figure.caption([C],position:top,separator:[S]).fields()'});rows=[]
for name,expr in cases.items():
 for kind,p in [('tekt','target/debug/typst'),('vanilla','lab/typst-original/target/release/typst')]:
  cmd=[str(Path(p).resolve()),'eval',expr,'--in',str(out/'empty.typ'),'--format','json'];r=subprocess.run(cmd,capture_output=True,text=True);rows.append(dict(name=name,binary=kind,expression=expr,argv=cmd,exit=r.returncode,stdout=r.stdout,stderr=r.stderr))
(out/('caption-shape-'+phase+'.json')).write_text(json.dumps(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_hashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in json.load(__import__('gzip').open(out/'before.json.gz','rt'))['hashes']},binary_build_source_hashes=json.load(open(out/'validation-result.json'))['source_hashes'],binaries={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in ['target/debug/typst','lab/typst-original/target/release/typst']},rows=rows),indent=2)+'\n')
for r in rows:print(r['name'],r['binary'],r['exit'],r['stdout'].strip()[:240],r['stderr'].splitlines()[:1])
